// app/(public)/ads/[id]/page.tsx
import { connectDB } from '../../../../lib/db'
import { Ad } from '@/models/ad'
import Image from 'next/image'
import { notFound } from 'next/navigation'

type Props = {
  params: {
    id: string
  }
}

export default async function AdDetailPage({ params }: Props) {
  await connectDB()

  // Tidak perlu await params
  const adRaw = await Ad.findById(params.id).lean()

  if (!adRaw || typeof adRaw._id !== 'object') return notFound()

  const ad = {
    _id: adRaw._id.toString(),
    title: adRaw.title,
    description: adRaw.description,
    category: adRaw.category,
    contact: adRaw.contact,
    imageUrl: adRaw.imageUrl,
    harga: adRaw.harga,
  }

  return (
    <div className="max-w-4xl mx-auto px-4 py-10">
      <Image
        src={ad.imageUrl}
        alt={ad.title}
        width={800}
        height={500}
        className="w-full h-96 object-cover rounded-xl mb-6"
      />
      <h1 className="text-3xl font-bold text-gray-800 mb-2">{ad.title}</h1>
      <p className="text-lg text-gray-600 italic mb-1">Kategori: {ad.category}</p>
      <p className="text-2xl text-green-700 font-bold mb-4">
        Rp {Number(ad.harga).toLocaleString('id-ID')}
      </p>
      <p className="text-gray-700 mb-6 whitespace-pre-line">{ad.description}</p>
      <a
        href={`https://wa.me/${ad.contact}?text=Halo, saya tertarik dengan hewan qurban bernama ${ad.title}`}
        target="_blank"
        className="inline-block bg-green-600 hover:bg-green-700 text-white px-6 py-3 rounded-lg font-semibold transition"
      >
        Hubungi via WhatsApp
      </a>
    </div>
  )
}
